    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_wallet_summary(WalletSummary self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.lastConfirmedHeight, serializer);
    sse_encode_u_64(self.minimumConfirmations, serializer);
    sse_encode_u_64(self.total, serializer);
    sse_encode_u_64(self.spendable, serializer);
    sse_encode_u_64(self.awaitingConfirmation, serializer);
    sse_encode_u_64(self.awaitingFinalization, serializer);
    sse_encode_u_64(self.immature, serializer);
    sse_encode_u_64(self.locked, serializer);
    sse_encode_bool(self.validatedWithNode, serializer);
  }
}

@sealed
class EpicWalletImpl extends RustOpaque implements EpicWallet {
  // Not to be used by end users
  EpicWalletImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  EpicWalletImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_EpicWallet,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_EpicWallet,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_EpicWalletPtr,
  );

  /// Cancels an unconfirmed transaction by log id and unlocks its outputs.
  Future<void> cancelTransaction({required int txId}) => RustLib.instance.api
      .crateApiWalletEpicWalletCancelTransaction(that: this, txId: txId);

  /// Address book, sorted by name.
  Future<List<Contact>> contacts() =>
      RustLib.instance.api.crateApiWalletEpicWalletContacts(that: this);

  /// Step 1 of a manual (file/JSON) send: builds the slate and locks the inputs.
  /// Hand `Slate.json` to the recipient; their response goes to `finalize_and_post`.
  Future<Slate> createSendSlate({
    required BigInt amount,
    required BigInt minimumConfirmations,
  }) => RustLib.instance.api.crateApiWalletEpicWalletCreateSendSlate(
    that: this,
    amount: amount,
    minimumConfirmations: minimumConfirmations,
  );

  Future<void> deleteContact({required String id}) => RustLib.instance.api
      .crateApiWalletEpicWalletDeleteContact(that: this, id: id);

  /// Fills in block heights and times, and settles imported records that were still pending,
  /// with at most 25 node calls and without refreshing outputs. Returns how many rows changed:
  /// reload `transactions(false)` only when it is above 0. Call it after the home screen loads;
  /// later calls carry on where a refused or failed lookup stopped.
  Future<int> enrichHistory() =>
      RustLib.instance.api.crateApiWalletEpicWalletEnrichHistory(that: this);

  /// The wallet's epicbox address, `<pubkey>@<epicbox_domain>` (port appended if not 443).
  Future<String> epicboxAddress() =>
      RustLib.instance.api.crateApiWalletEpicWalletEpicboxAddress(that: this);

  /// Fee the wallet would pay to send `amount` now.
  Future<FeeEstimate> estimateFee({
    required BigInt amount,
    required BigInt minimumConfirmations,
  }) => RustLib.instance.api.crateApiWalletEpicWalletEstimateFee(
    that: this,
    amount: amount,
    minimumConfirmations: minimumConfirmations,
  );

  /// The largest amount that can be sent now, and its fee. Sending `amount` spends every
  /// spendable output with no change.
  Future<FeeEstimate> estimateMax({required BigInt minimumConfirmations}) =>
      RustLib.instance.api.crateApiWalletEpicWalletEstimateMax(
        that: this,
        minimumConfirmations: minimumConfirmations,
      );

  /// The whole history (transactions, notes, contacts) as an encrypted file only a wallet with
  /// the same recovery phrase can open.
  Future<Uint8List> exportHistory() =>
      RustLib.instance.api.crateApiWalletEpicWalletExportHistory(that: this);

  /// The transaction list as CSV, for records. Not encrypted and not importable.
  Future<String> exportHistoryCsv() =>
      RustLib.instance.api.crateApiWalletEpicWalletExportHistoryCsv(that: this);

  /// Sender side: finalizes the recipient's response and posts the transaction to the node.
  Future<TxEntry> finalizeAndPost({required String slateJson}) =>
      RustLib.instance.api.crateApiWalletEpicWalletFinalizeAndPost(
        that: this,
        slateJson: slateJson,
      );

  /// Merges a file from `export_history` into this wallet's history. Importing the same file
  /// again changes nothing. A file from another wallet fails with `InvalidArgument`.
  Future<ImportReport> importHistory({required List<int> data}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletImportHistory(that: this, data: data);

  bool listenerRunning() =>
      RustLib.instance.api.crateApiWalletEpicWalletListenerRunning(that: this);

  /// Recovery phrase of this wallet, re-checked against `password`.
  Future<String> mnemonic({required String password}) => RustLib.instance.api
      .crateApiWalletEpicWalletMnemonic(that: this, password: password);

  /// Recipient side: signs an incoming send slate and returns the response slate JSON.
  Future<Slate> receiveSlate({required String slateJson}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletReceiveSlate(that: this, slateJson: slateJson);

  /// Posts a finalized send that never reached the chain to the node again (`TxEntry.repostable`).
  /// Its inputs stay locked until it confirms; there is no safe way to release them early.
  Future<void> repostTransaction({required String key}) => RustLib.instance.api
      .crateApiWalletEpicWalletRepostTransaction(that: this, key: key);

  /// Adds a contact (empty `id`) or replaces the one with that id. Returns it as stored.
  Future<Contact> saveContact({required Contact contact}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletSaveContact(that: this, contact: contact);

  /// Rescans the chain for this wallet's outputs from `start_height` (default: the wallet's
  /// last scanned height, or 1 for a restore), streaming progress until `finished`.
  Stream<ScanProgress> scan({BigInt? startHeight}) => RustLib.instance.api
      .crateApiWalletEpicWalletScan(that: this, startHeight: startHeight);

  /// Sends to `<address>@<relay>[:port]` over epicbox. Returns the new, still unfinalized
  /// transaction; the listener finalizes and posts it when the recipient's response arrives.
  Future<TxEntry> sendEpicbox({
    required BigInt amount,
    required BigInt minimumConfirmations,
    required String address,
  }) => RustLib.instance.api.crateApiWalletEpicWalletSendEpicbox(
    that: this,
    amount: amount,
    minimumConfirmations: minimumConfirmations,
    address: address,
  );

  /// Sends to a wallet listening on HTTP, e.g. `http://host:3415`. Completes the whole exchange:
  /// the recipient signs in the same request, then the transaction is finalized and posted.
  /// A failure before the post unlocks the outputs again. Receiving over HTTP is not offered:
  /// a phone cannot accept incoming connections.
  Future<TxEntry> sendHttp({
    required BigInt amount,
    required BigInt minimumConfirmations,
    required String url,
  }) => RustLib.instance.api.crateApiWalletEpicWalletSendHttp(
    that: this,
    amount: amount,
    minimumConfirmations: minimumConfirmations,
    url: url,
  );

  /// Sets the note of the transaction with `TxEntry.key`; `None` or blank clears it.
  Future<void> setTxNote({required String key, String? note}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletSetTxNote(that: this, key: key, note: note);

  /// Starts the epicbox listener (no-op if it already runs) and streams what it does. Incoming
  /// sends are signed and answered, responses to our sends are finalized and posted.
  Stream<ListenerEvent> startListener() =>
      RustLib.instance.api.crateApiWalletEpicWalletStartListener(that: this);

  /// Stops the listener. Takes up to about a second.
  Future<void> stopListener() =>
      RustLib.instance.api.crateApiWalletEpicWalletStopListener(that: this);

  /// Balances. With `refresh` the wallet first updates output state from the node.
  Future<WalletSummary> summary({
    required bool refresh,
    required BigInt minimumConfirmations,
  }) => RustLib.instance.api.crateApiWalletEpicWalletSummary(
    that: this,
    refresh: refresh,
    minimumConfirmations: minimumConfirmations,
  );

  /// Transactions, newest first by `time_unix`: epic-wallet's log merged with the app's history
  /// archive (notes, counterparties, imported records). With `refresh` it updates outputs from
  /// the node first. It makes no block or kernel lookups; see `enrich_history`.
  Future<List<TxEntry>> transactions({required bool refresh}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletTransactions(that: this, refresh: refresh);
}
